'use strict';

/**
 * The file-reading half of the brief renderer. `pr-review-briefs.js` is pure and takes
 * the template text as a parameter; this module is the one that finds the template
 * files on disk and reads them, so the pure modules the CLI loads stay free of I/O.
 *
 * The templates ship with the skill (`skills/pr-review-cycle/templates/`), so where
 * they are depends on how the CLI was installed:
 *
 *   packages/development/lib/            -> ../skills/pr-review-cycle/templates
 *   packages/full/lib/ (symlinks)        -> resolved to the real file above by node
 *   packages/pi/vendor/lib/              -> ../../skills/pr-review-cycle/templates
 *
 * Every candidate is tried in order and the first directory that holds the role's
 * template wins. Nothing is guessed: when none holds it, the render refuses and names
 * every place it looked.
 *
 * One thing is removed from what is read: the Pi generator copies every shipped markdown
 * file with a first line `<!-- Generated by ensemble-pi generator ... -->`, and a brief
 * that began with that comment would no longer be the policy text. Exactly that one
 * leading line is stripped; a comment anywhere else, or one a maintainer wrote, is kept.
 *
 * Dependencies are injectable (pattern: local-ci-runner.js `deps.run`):
 *   deps.readFile(path)  -> string, throws when unreadable   (default: fs.readFileSync utf8)
 *   deps.templateDirs    -> string[] of directories to try   (default: the layouts above)
 */

const fs = require('fs');
const path = require('path');

const { ROLES, renderBrief } = require('./pr-review-briefs');

const SKILL_TEMPLATES = path.join('skills', 'pr-review-cycle', 'templates');

/** The directories the templates live in for each supported install layout. */
function defaultTemplateDirs(libDir = __dirname) {
  return [path.resolve(libDir, '..', SKILL_TEMPLATES), path.resolve(libDir, '..', '..', SKILL_TEMPLATES)];
}

const defaultReadFile = (file) => fs.readFileSync(file, 'utf8');

/** The one line the Pi generator puts at the top of a copied markdown file. */
const GENERATED_MARKER_LINE = /^<!-- Generated by ensemble-pi generator [^\n]*-->\r?\n/;

/**
 * The text of a role's template file.
 * @throws when the role is unknown or no candidate directory holds the template
 */
function loadTemplate(role, deps = {}) {
  if (typeof role !== 'string' || !Object.prototype.hasOwnProperty.call(ROLES, role)) {
    // Let the pure module say it: one wording for an unknown role.
    renderBrief(role, {}, '');
  }
  const readFile = deps.readFile || defaultReadFile;
  const dirs = deps.templateDirs || defaultTemplateDirs();
  const tried = [];
  for (const dir of dirs) {
    const file = path.join(dir, ROLES[role].template);
    try {
      const text = readFile(file);
      return typeof text === 'string' ? text.replace(GENERATED_MARKER_LINE, '') : text;
    } catch (error) {
      tried.push(`${file} (${error && error.code ? error.code : 'unreadable'})`);
    }
  }
  throw new Error(`cannot find the ${role} brief template ${ROLES[role].template}; looked in: ${tried.join('; ')}`);
}

/** `renderBrief(role, vars)` over the template files on disk. */
function renderBriefFromFiles(role, vars, deps = {}) {
  return renderBrief(role, vars, loadTemplate(role, deps));
}

module.exports = { defaultTemplateDirs, loadTemplate, renderBriefFromFiles };
